window.PET_DATA["knowledge/vocab-technology.json"] = {"id":"vocab-technology","type":"vocab","title":"Vocabulary: Communications & Technology","topic":"technology","objective":"Digital life vocabulary from the PET syllabus — useful for technology articles and Speaking Part 3.","sections":[],"items":[{"id":"v_tec_001","word":"app","pos":"noun","meaning":"a small computer program for a phone or tablet","meaningZh":"应用程序","example":"I use an app to practise English every day.","exampleZh":"我每天用一个应用练习英语。"},{"id":"v_tec_002","word":"connect","pos":"verb","meaning":"to join something to the internet or to another device","meaningZh":"连接","example":"I can't connect my phone to the Wi-Fi.","exampleZh":"我的手机连不上无线网。"},{"id":"v_tec_003","word":"delete","pos":"verb","meaning":"to remove something from a computer or phone","meaningZh":"删除","example":"I deleted that photo by mistake.","exampleZh":"我不小心删掉了那张照片。"},{"id":"v_tec_004","word":"download","pos":"verb / noun","meaning":"to copy a file or app from the internet to your device","meaningZh":"下载","example":"You can download the game for free.","exampleZh":"你可以免费下载这款游戏。"},{"id":"v_tec_005","word":"upload","pos":"verb","meaning":"to send a file from your device to the internet","meaningZh":"上传","example":"She uploaded the video to social media.","exampleZh":"她把视频上传到了社交媒体。"},{"id":"v_tec_006","word":"email","pos":"noun / verb","meaning":"a message sent electronically; to send such a message","meaningZh":"电子邮件；发电子邮件","example":"I'll email you the directions tonight.","exampleZh":"我今晚会把路线发邮件给你。"},{"id":"v_tec_007","word":"file","pos":"noun","meaning":"a collection of information stored under one name on a computer","meaningZh":"文件","example":"Save your file before you close the program.","exampleZh":"关闭程序前先保存文件。"},{"id":"v_tec_008","word":"install","pos":"verb","meaning":"to put software on a computer or phone so it can be used","meaningZh":"安装","example":"The update takes a few minutes to install.","exampleZh":"安装更新需要几分钟。"},{"id":"v_tec_009","word":"internet","pos":"noun","meaning":"the worldwide computer network that connects people and information","meaningZh":"互联网","example":"I looked up the answer on the internet.","exampleZh":"我在网上查了答案。"},{"id":"v_tec_010","word":"keyboard","pos":"noun","meaning":"the set of keys used for typing on a computer","meaningZh":"键盘","example":"This keyboard is easier to type on.","exampleZh":"这个键盘打字更轻松。"},{"id":"v_tec_011","word":"laptop","pos":"noun","meaning":"a small computer that you can carry","meaningZh":"笔记本电脑","example":"She does her homework on a laptop.","exampleZh":"她用笔记本电脑做作业。"},{"id":"v_tec_012","word":"message","pos":"noun","meaning":"a short piece of written or spoken information sent to someone","meaningZh":"信息、留言","example":"Leave me a message if I'm not in.","exampleZh":"如果我不在，请给我留言。"},{"id":"v_tec_013","word":"online / offline","pos":"adjective / adverb","meaning":"connected to the internet / not connected to the internet","meaningZh":"在线 / 离线","example":"You can pay online or in the shop.","exampleZh":"你可以在线支付，也可以在店里支付。"},{"id":"v_tec_014","word":"password","pos":"noun","meaning":"a secret word or numbers needed to enter a website or device","meaningZh":"密码","example":"Choose a strong password that is hard to guess.","exampleZh":"选一个很难猜到的强密码。"},{"id":"v_tec_015","word":"printer","pos":"noun","meaning":"a machine that puts words and pictures from a computer onto paper","meaningZh":"打印机","example":"The printer has run out of paper.","exampleZh":"打印机没纸了。"},{"id":"v_tec_016","word":"screen","pos":"noun","meaning":"the flat surface of a phone, computer or television where images appear","meaningZh":"屏幕","example":"Don't sit too close to the screen.","exampleZh":"别坐得离屏幕太近。"},{"id":"v_tec_017","word":"share","pos":"verb","meaning":"to let others see or use something online","meaningZh":"分享","example":"She shared the photos with her classmates.","exampleZh":"她和同学们分享了这些照片。"},{"id":"v_tec_018","word":"social media","pos":"noun","meaning":"websites and apps where people share news, photos and opinions","meaningZh":"社交媒体","example":"He spends too much time on social media.","exampleZh":"他在社交媒体上花的时间太多了。"},{"id":"v_tec_019","word":"turn on / turn off","pos":"phrasal verbs","meaning":"to start / stop a device working","meaningZh":"打开 / 关闭","example":"Turn off your phone during the exam.","exampleZh":"考试期间请关闭手机。"},{"id":"v_tec_020","word":"website","pos":"noun","meaning":"a place on the internet with pages of information about a subject","meaningZh":"网站","example":"The school's website has the exam timetable.","exampleZh":"学校网站上有考试时间表。"}],"summary":{"keyPoints":["Learn pairs of opposites: download/upload, turn on/turn off, online/offline.","Use post and share for social media, but send and reply for messages and emails.","In Speaking, say why technology is useful, not just list devices."],"mustKnow":["download","upload","share","social media","password","website"]},"linkedPractice":["review"],"reviewItems":["v_tec_001","v_tec_002","v_tec_003","v_tec_004","v_tec_005","v_tec_006","v_tec_007","v_tec_008","v_tec_009","v_tec_010","v_tec_011","v_tec_012","v_tec_013","v_tec_014","v_tec_015","v_tec_016","v_tec_017","v_tec_018","v_tec_019","v_tec_020"]};
